<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { ChevronDown, FileSignature, FileText, Files, LayoutDashboard, LayoutTemplate, ListChecks, LogOut, Plus, Settings, SlidersHorizontal, UserCog, Wallet } from 'lucide-vue-next'
import FulfillmentWorkspace from './components/FulfillmentWorkspace.vue'
import ChangeWorkspace from './components/ChangeWorkspace.vue'
import ContractLedgerWorkspace from './components/ContractLedgerWorkspace.vue'
import BaseConfigWorkspace from './components/BaseConfigWorkspace.vue'
import CreateContractWorkspace from './components/CreateContractWorkspace.vue'
import FormalContractPanel from './components/FormalContractPanel.vue'
import AiExtractionReview from './components/AiExtractionReview.vue'
import AdminUserWorkspace from './components/AdminUserWorkspace.vue'
import ContractAuthorizationWorkspace from './components/ContractAuthorizationWorkspace.vue'
import SignedContractRegistration from './components/SignedContractRegistration.vue'

type Type = { id: number; name: string; subtype: string; category: string; enabled: boolean }
type Party = { id: string; name: string; relationType: string; sourceType: string; nature: string }
type Contract = { id: number; contractNo: string; name: string; typeName: string; partyName: string; status: string; updatedAt: string }
type Detail = Contract & { typeId: number; partyId: string; relationType: string; sourceType: string; remark: string; version: number; totalAmount: number | null; currency: string | null; paymentDirection: string | null; signDate: string | null; effectiveDate: string | null; expireDate: string | null; sourceTypeCode: string | null; archived: boolean; auditEntries: { description: string; operatedAt: string }[]; contentVersions: { id: number; versionNo: number; source: string; contentHash: string; current: boolean }[]; attachments: { id: number; fileName: string; fileSize: number; fileRef: string; bizAttachType?: number }[] }
type Template = { id: number; name: string; typeId: number; typeName: string; status: string; versionNo: number; updatedAt: string }
type Payment = { id: number; itemName: string; direction: string; amount: number; dueDate: string; status: string }
type Milestone = { id: number; name: string; dueDate: string; status: string }
type AiTask = { id: number; taskType: string; status: string; summary: string }
type Review = { overallLevel: string; summary: string; confirmed: boolean; risks: { level: string; riskPoint: string; advice: string }[] }
type Approval = { id: number; approvalNo: string; status: 'PENDING'|'APPROVED'|'REJECTED'|'WITHDRAWN'; result: string | null; updatedAt: string }
type CurrentUser = { displayName: string; role: string; permissions: string[] }
type MockUser = { id: string; name: string; role: string; orgId: string; departmentId: string }

const api = import.meta.env.VITE_API_BASE || ''
const view = ref<'workspace'|'ledger'|'fulfillment'|'base-config'|'accounts'|'create'|'register'|'detail'|'changes'|'authorization'>('workspace')
const ledgerStatus = ref('')
const authenticated = ref(false)
const loginForm = ref({ account: '', password: '' })
const loginError = ref('')
const loginLoading = ref(false)
const expandedGroups = ref({ contract: true, system: false })
const types = ref<Type[]>([]); const parties = ref<Party[]>([]); const contracts = ref<Contract[]>([]); const templates = ref<Template[]>([])
const selected = ref<Detail | null>(null); const error = ref(''); const loading = ref(false); const search = ref(''); const uploadInput = ref<HTMLInputElement | null>(null)
const detailTab = ref<'overview'|'content'|'approval'|'fulfillment'|'archive'>('overview')
const uploadType = ref(3)
const effectiveForm = ref({ signedFileId: null as number | null, signDate: '', effectiveDate: '' })
const content = ref(''); const payments = ref<Payment[]>([]); const milestones = ref<Milestone[]>([]); const tasks = ref<AiTask[]>([]); const review = ref<Review|null>(null); const approval = ref<Approval|null>(null)
const currentUser = ref<CurrentUser>({ displayName: '本地用户', role: 'ADMIN', permissions: ['VIEW', 'EDIT', 'APPROVE', 'FULFILL', 'TEMPLATE'] })
const mockIdentity = ref<MockUser>({ id: '10001', name: '本地管理员', role: 'ADMIN', orgId: '100', departmentId: '101' })
const form = ref({ typeId: 1, partyId: '', name: '', remark: '', templateId: null as number|null, totalAmount: null as number | null, currency: 'CNY', paymentDirection: null as number | null, expireDate: '' })
const paymentForm = ref({ itemName: '', direction: 'PAY', amount: 0, dueDate: '' }); const milestoneForm = ref({ name: '', dueDate: '' })
const templateForm = ref({ name: '', typeId: 1, content: '合同名称：{{contract.name}}\n合同编号：{{contract.no}}\n交易对方：{{party.name}}\n\n一、双方权利义务\n' })

function groupForView(value: typeof view.value) {
  if (['workspace', 'ledger', 'fulfillment', 'create', 'register', 'detail', 'changes', 'authorization'].includes(value)) return 'contract' as const
  return 'system' as const
}
function navigate(value: typeof view.value) {
  view.value = value
  expandedGroups.value[groupForView(value)] = true
}
function drillToStatistics(target: 'ledger' | 'fulfillment', status?: string) {
  if (target === 'ledger') ledgerStatus.value = status || ''
  navigate(target)
}
async function login() {
  loginError.value = ''
  if (!loginForm.value.account.trim() || !loginForm.value.password) {
    loginError.value = '请输入账号和密码'
    return
  }
  loginLoading.value = true
  try {
    const response = await fetch(`${api}/api/auth/login`, { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(loginForm.value) })
    if (!response.ok) throw new Error((await response.text()) || '登录失败')
    const user = await response.json(); mockIdentity.value = { id: user.userId, name: user.displayName, role: user.role, orgId: user.orgId, departmentId: user.departmentId }; currentUser.value = { ...currentUser.value, displayName: user.displayName, role: user.role }; authenticated.value = true; await loadBase()
  } catch (e) { loginError.value = (e as Error).message } finally { loginLoading.value = false }
}
function logout() {
  fetch(`${api}/api/auth/logout`, { method: 'POST', credentials: 'include' }).catch(() => undefined)
  authenticated.value = false
  selected.value = null
  view.value = 'workspace'
}
function oidcLogin() { const target = ['workspace', 'ledger', 'fulfillment', 'base-config', 'accounts'].includes(view.value) ? view.value : 'workspace'; window.location.href = `${api}/api/auth/oidc/login?returnTo=${encodeURIComponent(target)}` }
function toggleGroup(group: keyof typeof expandedGroups.value) {
  expandedGroups.value[group] = !expandedGroups.value[group]
  localStorage.setItem('contract-system.nav.expanded', JSON.stringify(expandedGroups.value))
}
watch(expandedGroups, value => localStorage.setItem('contract-system.nav.expanded', JSON.stringify(value)), { deep: true })
watch(view, value => { expandedGroups.value[groupForView(value)] = true })

async function request<T>(path: string, options?: RequestInit): Promise<T> { const response = await fetch(`${api}${path}`, { credentials: 'include', headers: { 'Content-Type': 'application/json', 'X-Role': mockIdentity.value.role, 'X-User-Id': mockIdentity.value.id, 'X-Org-Id': mockIdentity.value.orgId, 'X-Department-Id': mockIdentity.value.departmentId, ...(options?.headers || {}) }, ...options }); if (!response.ok) { if (response.status === 401) { authenticated.value = false; loginError.value = '登录已失效，请重新登录' }; const raw = await response.text(); try { const parsed = JSON.parse(raw); throw new Error(parsed.message || '请求失败') } catch (e) { if (e instanceof Error && e.message !== raw) throw e; throw new Error(raw || '请求失败') } }; return response.json() }
async function loadBase() { [currentUser.value, types.value, parties.value, contracts.value, templates.value] = await Promise.all([request<CurrentUser>('/api/me'), request<Type[]>('/api/contract-types'), request<Party[]>('/api/trade-parties'), request<Contract[]>('/api/contracts'), request<Template[]>('/api/templates')]); loadOverview() }
async function openContract(id: number) { try { selected.value = await request<Detail>(`/api/contracts/${id}`); [tasks.value, review.value, payments.value, milestones.value, approval.value] = await Promise.all([request<AiTask[]>(`/api/contracts/${id}/ai/tasks`), request<Review|null>(`/api/contracts/${id}/ai/review`), request<Payment[]>(`/api/contracts/${id}/payments`), request<Milestone[]>(`/api/contracts/${id}/milestones`), request<Approval|null>(`/api/contracts/${id}/approval`)]); content.value = ''; detailTab.value = 'overview'; view.value = 'detail' } catch (e) { error.value = (e as Error).message } }
async function openRegisteredContract(id: number) {
  await openContract(id)
  if (view.value === 'detail') detailTab.value = selected.value?.status === '履行中' ? 'fulfillment' : 'content'
}
const filtered = computed(() => { const q = search.value.trim().toLowerCase(); return q ? contracts.value.filter(c => [c.name, c.contractNo, c.typeName, c.partyName].some(v => v.toLowerCase().includes(q))) : contracts.value })
const counts = computed(() => ({ total: contracts.value.length, draft: contracts.value.filter(c => c.status === '草稿').length, sign: contracts.value.filter(c => c.status === '待签署').length, active: contracts.value.filter(c => c.status === '履行中').length }))
const displayCounts = ref({ total: 0, draft: 0, sign: 0, active: 0 })
const metricBars = computed(() => { const t = counts.value.total || 1; return { draft: Math.round(counts.value.draft / t * 100), sign: Math.round(counts.value.sign / t * 100), active: Math.round(counts.value.active / t * 100) } })
function animateCount(key: 'total' | 'draft' | 'sign' | 'active', to: number) { const from = displayCounts.value[key]; if (from === to) { displayCounts.value[key] = to; return }; const start = performance.now(); const dur = 720; const step = (now: number) => { const t = Math.min(1, (now - start) / dur); const eased = 1 - Math.pow(1 - t, 3); displayCounts.value[key] = Math.round(from + (to - from) * eased); if (t < 1) requestAnimationFrame(step) }; requestAnimationFrame(step) }
watch(counts, c => { animateCount('total', c.total); animateCount('draft', c.draft); animateCount('sign', c.sign); animateCount('active', c.active) }, { immediate: true })
type RiskBucket = { key: string; label: string; count: number; amount: number | null }
type AttentionItem = { key: string; category: string; severity: string; contractId: number; contractNo: string; contractName: string; title: string; detail: string; dueDate: string | null; target: 'CONTRACT' | 'FULFILLMENT'; handlingStatus: 'OPEN'|'PROCESSED'|'IGNORED'; handlingOpinion: string | null; handledBy: string | null; handledAt: string | null; escalated: boolean }
type WorkspaceOverview = { valid: number; completed: number; aiPending: number; aiFailed: number; highRisk: number; paymentOverdue: number; milestoneOverdue: number; paymentPending: number; milestonePending: number; paymentTotal: number; paidTotal: number; aiRisks: RiskBucket[] }
const overview = ref<WorkspaceOverview | null>(null)
const attentionItems = ref<AttentionItem[]>([])
const showNotifications = ref(false)
const showCreateDialog = ref(false)
const registrationPath = ref<'pending' | 'signed'>('signed')
async function loadOverview() { try { const headers = { 'X-Role': mockIdentity.value.role, 'X-User-Id': mockIdentity.value.id, 'X-Org-Id': mockIdentity.value.orgId, 'X-Department-Id': mockIdentity.value.departmentId }; const [overviewResponse, attentionResponse] = await Promise.all([fetch(`${api}/api/statistics/overview`, { credentials: 'include', headers }), fetch(`${api}/api/attention-items`, { credentials: 'include', headers })]); if (overviewResponse.ok) overview.value = await overviewResponse.json(); if (attentionResponse.ok) attentionItems.value = await attentionResponse.json() } catch { /* 统计加载失败不阻塞工作台 */ } }
const notificationCount = computed(() => attentionItems.value.filter(item => item.handlingStatus === 'OPEN').length)
async function openAttention(item: AttentionItem) { showNotifications.value = false; if (item.target === 'FULFILLMENT') navigate('fulfillment'); await openContract(item.contractId) }
async function updateAttention(item: AttentionItem, status: 'PROCESSED'|'IGNORED'|'OPEN') { const opinion = status === 'OPEN' ? '' : window.prompt(status === 'PROCESSED' ? '填写处理意见' : '填写忽略原因', item.handlingOpinion || ''); if (opinion === null) return; try { const updated = await request<AttentionItem>(`/api/attention-items/${encodeURIComponent(item.key)}/handling`, { method: 'POST', body: JSON.stringify({ status, opinion }) }); attentionItems.value = attentionItems.value.map(entry => entry.key === updated.key ? updated : entry); } catch (e) { error.value = (e as Error).message } }
async function exportAnalysis() { try { const response = await fetch(`${api}/api/exports/analysis`, { credentials: 'include', headers: { 'X-Role': mockIdentity.value.role, 'X-User-Id': mockIdentity.value.id, 'X-Org-Id': mockIdentity.value.orgId, 'X-Department-Id': mockIdentity.value.departmentId } }); if (!response.ok) throw new Error((await response.text()) || '导出失败'); const url = URL.createObjectURL(await response.blob()); const link = document.createElement('a'); link.href = url; link.download = `contract-analysis-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(url); } catch (e) { error.value = (e as Error).message } }
const paymentRate = computed(() => { const total = Number(overview.value?.paymentTotal ?? 0); const paid = Number(overview.value?.paidTotal ?? 0); return total > 0 ? Math.round(paid / total * 100) : 0 })
const aiRiskTotal = computed(() => (overview.value?.aiRisks ?? []).reduce((sum, bucket) => sum + bucket.count, 0))
function riskPct(level: string) { const total = aiRiskTotal.value || 1; const bucket = (overview.value?.aiRisks ?? []).find(item => item.key === level); return bucket ? Math.round(bucket.count / total * 100) : 0 }
function money(amount: number | null | undefined) { const n = Number(amount ?? 0); if (Math.abs(n) >= 100000000) return (n / 100000000).toFixed(2) + ' 亿'; if (Math.abs(n) >= 10000) return (n / 10000).toFixed(1) + ' 万'; return n.toFixed(0) }
const categoryCounts = computed(() => types.value.map(type => ({ ...type, count: contracts.value.filter(item => item.typeName === type.name).length })).filter(type => type.count > 0))
const attentionCount = computed(() => counts.value.draft + counts.value.sign)
function startCreate() { selected.value = null; form.value = { typeId: types.value[0]?.id || 1, partyId: parties.value[0]?.id || '', name: '', remark: '', templateId: null, totalAmount: null, currency: 'CNY', paymentDirection: null, expireDate: '' }; showCreateDialog.value = true }
function chooseCreatePath(path: 'template' | 'pending' | 'signed') { showCreateDialog.value = false; if (path === 'template') navigate('create'); else { registrationPath.value = path; navigate('register') } }
function editSelected() { if (!selected.value) return; form.value = { typeId: selected.value.typeId, partyId: selected.value.partyId, name: selected.value.name, remark: selected.value.remark || '', templateId: null, totalAmount: selected.value.totalAmount, currency: selected.value.currency || 'CNY', paymentDirection: selected.value.paymentDirection ? Number(selected.value.paymentDirection) : null, expireDate: selected.value.expireDate || '' }; view.value = 'create' }
async function saveDraft(draftContent = '') {
  if (!form.value.name.trim()) { error.value = '请输入合同名称'; return }
  loading.value = true
  try {
    selected.value = selected.value
      ? await request<Detail>(`/api/contracts/${selected.value.id}/draft`, { method: 'PUT', body: JSON.stringify({ ...form.value, version: selected.value.version }) })
      : await request<Detail>('/api/contracts', { method: 'POST', body: JSON.stringify(form.value) })
    if (draftContent.trim() && selected.value) await request(`/api/contracts/${selected.value.id}/content-versions`, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: draftContent })
    await loadBase(); view.value = 'detail'; if (selected.value) await openContract(selected.value.id)
  } catch (e) { error.value = (e as Error).message } finally { loading.value = false }
}
async function action(path: string, body?: unknown) { try { await request(path, { method: 'POST', ...(body === undefined ? {} : { body: JSON.stringify(body) }) }); if (selected.value) await openContract(selected.value.id); await loadBase() } catch (e) { error.value = (e as Error).message } }
async function saveContent() { if (!selected.value || !content.value.trim()) { error.value = '请输入合同正文'; return }; try { await request(`/api/contracts/${selected.value.id}/content-versions`, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: content.value }); await openContract(selected.value.id) } catch (e) { error.value = (e as Error).message } }
async function uploadFile(event: Event) { if (!selected.value) return; const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; const data = new FormData(); data.append('file', file); try { await request(`/api/contracts/${selected.value.id}/attachments?bizAttachType=${uploadType.value}`, { method: 'POST', headers: {}, body: data }); await openContract(selected.value.id) } catch (e) { error.value = (e as Error).message }; if (uploadInput.value) uploadInput.value.value = '' }
async function confirmEffective() { if (!selected.value || !effectiveForm.value.signedFileId || !effectiveForm.value.signDate || !effectiveForm.value.effectiveDate) { error.value = '请先选择签署文件并填写签署日期、生效日期'; return }; try { await request(`/api/contracts/${selected.value.id}/effective?signedFileId=${effectiveForm.value.signedFileId}&signDate=${effectiveForm.value.signDate}&effectiveDate=${effectiveForm.value.effectiveDate}`, { method: 'POST' }); await openContract(selected.value.id); detailTab.value = 'fulfillment' } catch (e) { error.value = (e as Error).message } }
async function confirmReview() { if (selected.value) await action(`/api/contracts/${selected.value.id}/ai/review/confirm`) }
async function createTemplate() { if (!templateForm.value.name.trim() || !templateForm.value.content.trim()) { error.value = '请填写模板名称和正文'; return }; await action('/api/templates', templateForm.value); templateForm.value = { name: '', typeId: types.value[0]?.id || 1, content: '合同名称：{{contract.name}}\n合同编号：{{contract.no}}\n交易对方：{{party.name}}\n\n一、双方权利义务\n' } }
async function addPayment() { if (selected.value) { await action(`/api/contracts/${selected.value.id}/payments`, paymentForm.value); paymentForm.value = { itemName: '', direction: 'PAY', amount: 0, dueDate: '' } } }
async function addMilestone() { if (selected.value) { await action(`/api/contracts/${selected.value.id}/milestones`, milestoneForm.value); milestoneForm.value = { name: '', dueDate: '' } } }
onMounted(async () => {
  try { const response = await fetch(`${api}/api/auth/session`, { credentials: 'include' }); if (!response.ok) return; const user = await response.json(); mockIdentity.value = { id: user.userId, name: user.displayName, role: user.role, orgId: user.orgId, departmentId: user.departmentId }; currentUser.value = { ...currentUser.value, displayName: user.displayName, role: user.role }; authenticated.value = true } catch { return }
  const saved = localStorage.getItem('contract-system.nav.expanded')
  if (saved) {
    try { expandedGroups.value = { ...expandedGroups.value, ...JSON.parse(saved) } } catch { /* ignore invalid local UI state */ }
  }
  try { await loadBase(); const target = new URLSearchParams(window.location.search).get('portalTarget'); if (target && ['workspace', 'ledger', 'fulfillment', 'base-config', 'accounts'].includes(target)) { navigate(target as typeof view.value); window.history.replaceState({}, '', window.location.pathname) } } catch (e) { error.value = (e as Error).message }
})
</script>

<template>
  <nav v-if="view === 'detail' && selected" class="detail-tabs" aria-label="合同详情导航"><button :class="{ active: detailTab === 'overview' }" @click="detailTab='overview'">概览</button><button :class="{ active: detailTab === 'content' }" @click="detailTab='content'">正文与文件</button><button :class="{ active: detailTab === 'approval' }" @click="detailTab='approval'">审批与签署</button><button :class="{ active: detailTab === 'fulfillment' }" @click="detailTab='fulfillment'">履约与收付款</button><button :class="{ active: detailTab === 'archive' }" @click="detailTab='archive'">变更与归档</button></nav>
  <div v-if="view === 'detail' && selected" class="detail-actions">
    <button v-if="currentUser.permissions.includes('TEMPLATE')" class="change-entry" @click="view='authorization'">合同级授权</button>
  </div>
  <section v-if="view === 'detail' && selected && selected.status === '待签署'" class="signing-dock"><div><strong>签署生效</strong><small>上传签署文件并确认后进入履行中</small></div><label>附件类型<select v-model.number="uploadType"><option :value="2">签署文件</option><option :value="1">合同原件</option><option :value="3">证明材料</option><option :value="4">变更协议附件</option></select></label><label>签署文件<select v-model.number="effectiveForm.signedFileId"><option :value="null">请选择签署文件</option><option v-for="file in selected.attachments.filter(item => item.bizAttachType === 2)" :key="file.id" :value="file.id">{{ file.fileName }}</option></select></label><label>签署日期<input v-model="effectiveForm.signDate" type="date" /></label><label>生效日期<input v-model="effectiveForm.effectiveDate" type="date" /></label><label class="secondary-action upload-button">上传文件<input ref="uploadInput" type="file" hidden @change="uploadFile" /></label><button class="primary-action" @click="confirmEffective">确认生效</button></section>
  <div v-if="authenticated && showCreateDialog" class="create-path-modal-backdrop" @click.self="showCreateDialog=false"><section class="create-path-modal" role="dialog" aria-modal="true" aria-labelledby="create-path-title"><div class="modal-heading"><div><p class="eyebrow">NEW CONTRACT</p><h2 id="create-path-title">新建合同</h2><p>请选择合同当前所处的真实阶段，系统会据此安排后续审查、审批和签署。</p></div><button class="modal-close" aria-label="关闭" @click="showCreateDialog=false">×</button></div><div class="create-path-options"><button @click="chooseCreatePath('template')"><b>模板起草</b><span>尚未形成对方文件，从公司标准模板拟定合同。</span><small>起草 → 审查 → 审批 → 签署</small></button><button @click="chooseCreatePath('pending')"><b>上传待审合同</b><span>对方提供了未签 Word、PDF 或扫描件，需要审查后再签。</span><small>上传 → 解析确认 → 法审 → 审批 → 签署</small></button><button @click="chooseCreatePath('signed')"><b>登记已签合同</b><span>历史、线下或已签合同，上传原件后做核验和履约登记。</span><small>上传 → 解析确认 → 履约</small></button></div></section></div>
  <section v-if="!authenticated" class="login-screen">
    <div class="login-brand"><span class="brand-mark">C</span><div><strong>合同管理系统</strong><small>企业合同全生命周期管理</small></div></div>
    <div class="login-layout">
      <div class="login-intro"><p class="eyebrow">CONTRACT OPERATIONS</p><h1>让每一份合同<br>都处于可控状态</h1><p>统一管理合同台账、审批、履行、收付款与审计记录，帮助业务团队在一个工作区内完成协作。</p><div class="login-points"><span>合同全生命周期</span><span>权限与数据范围</span><span>审计记录可追溯</span></div></div>
      <form class="login-panel" @submit.prevent="login"><div class="login-heading"><span class="login-kicker">企业工作台</span><h2>登录系统</h2><p>使用组织账号进入合同管理工作区</p></div><label>账号<input v-model="loginForm.account" autocomplete="username" placeholder="请输入账号" /></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" placeholder="请输入密码" /></label><p v-if="loginError" class="login-error">{{ loginError }}</p><button class="primary-action login-submit" type="submit" :disabled="loginLoading">{{ loginLoading ? '正在登录...' : '登录' }}</button><button class="iam-login-button" type="button" @click="oidcLogin">使用企业门户登录</button><div class="login-help"><span>账号认证由 IAM 统一处理</span><span>请联系管理员开通权限</span></div></form>
    </div>
    <footer class="login-footer">© 2026 合同管理系统 · 企业内部使用</footer>
  </section>
  <div v-else class="app-shell" :class="{ 'detail-tab-overview': view === 'detail' && detailTab === 'overview', 'detail-tab-content': view === 'detail' && detailTab === 'content', 'detail-tab-approval': view === 'detail' && detailTab === 'approval', 'detail-tab-fulfillment': view === 'detail' && detailTab === 'fulfillment', 'detail-tab-archive': view === 'detail' && detailTab === 'archive', 'fulfillment-mode': view === 'fulfillment', 'ledger-mode': view === 'ledger' }">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark"><FileSignature :size="22" :stroke-width="2.2" /></span><span>合同管理系统</span></div>
      <section class="nav-group">
