     <main class="main-content"><header class="topbar"><div class="topbar-title"><strong>{{ view === 'workspace' ? '合同工作台' : view === 'ledger' ? '合同台账' : view === 'fulfillment' ? '履行与收付款' : view === 'base-config' ? '基础配置' : view === 'accounts' ? '账号管理' : view === 'create' ? '新建合同' : view === 'authorization' ? '合同级授权' : view === 'changes' ? '变更与补充协议' : '合同详情' }}</strong><span class="breadcrumb">合同管理 / {{ view === 'workspace' ? '工作台' : view === 'ledger' ? '合同台账' : view === 'fulfillment' ? '履行与收付款' : view === 'base-config' ? '基础配置' : view === 'accounts' ? '账号管理' : view === 'create' ? '新建合同' : view === 'authorization' ? '合同级授权' : view === 'changes' ? '变更与补充协议' : '合同详情' }}</span></div><span class="topbar-context">系统连接正常</span></header><div v-if="error" class="alert">{{ error }}<button @click="error=''">关闭</button></div>
      <section v-if="view === 'workspace'" class="page-section workspace-page"><div class="tech-hero"><div class="tech-hero-grid" aria-hidden="true"></div><div class="page-header"><div><p class="eyebrow">CONTRACT OPERATIONS</p><h1>合同工作台</h1><p class="page-desc">把审批、签署、AI 审查和履行事项放在同一处处理。</p></div><div class="header-actions"><div class="workspace-search"><input v-model="search" placeholder="搜索合同名称 / 编号 / 对方" @keyup.enter="navigate('ledger')" /><span class="search-kbd">↵</span></div><div class="notify-wrap"><button class="notify-bell" :class="{ active: showNotifications }" @click="showNotifications = !showNotifications"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.7 21a2 2 0 0 1-3.4 0"/></svg><span v-if="notificationCount" class="notify-dot">{{ notificationCount }}</span></button><transition name="drop"><div v-if="showNotifications" class="notify-panel"><div class="notify-head">关注事项<span class="muted">{{ notificationCount }} 项待跟进</span></div><button class="notify-item" @click="showNotifications = false; navigate('ledger')"><i class="dot dot-ai"></i><span><b>待确认 AI 结果</b><small>解析与审查结果待人工确认</small></span><strong>{{ overview?.aiPending ?? 0 }}</strong></button><button class="notify-item" @click="showNotifications = false; navigate('ledger')"><i class="dot dot-risk"></i><span><b>高风险合同</b><small>法律审查标记为高风险</small></span><strong>{{ overview?.highRisk ?? 0 }}</strong></button><button class="notify-item" @click="showNotifications = false; navigate('fulfillment')"><i class="dot dot-pay"></i><span><b>逾期付款</b><small>收付款计划已到期</small></span><strong>{{ overview?.paymentOverdue ?? 0 }}</strong></button><button class="notify-item" @click="showNotifications = false; navigate('fulfillment')"><i class="dot dot-milestone"></i><span><b>履行节点逾期</b><small>履行事项已到期</small></span><strong>{{ overview?.milestoneOverdue ?? 0 }}</strong></button></div></transition></div><button class="primary-action" @click="startCreate">＋ 新建合同</button></div></div></div><div class="metric-grid"><button class="metric-card metric-total" @click="view='ledger'"><span class="metric-glyph"><Files :size="20" :stroke-width="1.75" /></span><span class="metric-label">合同总数</span><strong class="metric-value">{{ displayCounts.total }}</strong><small>有效 {{ overview?.valid ?? displayCounts.total }} · 已完成 {{ overview?.completed ?? 0 }}</small></button><button class="metric-card metric-draft" @click="view='ledger'"><span class="metric-glyph"><FileText :size="20" :stroke-width="1.75" /></span><span class="metric-label">草稿</span><strong class="metric-value">{{ displayCounts.draft }}</strong><small>待继续编辑</small><span class="metric-bar"><b :style="{ width: metricBars.draft + '%' }"></b></span><span class="metric-action" @click.stop="view='ledger'">继续编辑 →</span></button><button class="metric-card metric-sign" @click="view='ledger'"><span class="metric-glyph"><FileSignature :size="20" :stroke-width="1.75" /></span><span class="metric-label">待签署</span><strong class="metric-value">{{ displayCounts.sign }}</strong><small>审批已通过</small><span class="metric-bar"><b :style="{ width: metricBars.sign + '%' }"></b></span><span class="metric-action" @click.stop="view='ledger'">去签署 →</span></button><button class="metric-card metric-active" @click="navigate('fulfillment')"><span class="metric-glyph"><Wallet :size="20" :stroke-width="1.75" /></span><span class="metric-label">履行中</span><strong class="metric-value">{{ displayCounts.active }}</strong><small>正在执行</small><span class="metric-bar"><b :style="{ width: metricBars.active + '%' }"></b></span><span class="metric-action" @click.stop="navigate('fulfillment')">看履行 →</span></button></div><div class="cockpit-grid"><section class="panel health-panel"><div class="section-heading"><div><h2>资金与履约健康度</h2><p class="section-caption">收付款执行率与履行节点完成进度</p></div></div><div class="health-body"><div class="payment-ring"><svg class="ring" viewBox="0 0 120 120"><circle class="ring-bg" cx="60" cy="60" r="52" /><circle class="ring-fg" cx="60" cy="60" r="52" :style="{ strokeDashoffset: 326.7 * (1 - paymentRate / 100) }" /></svg><div class="ring-center"><strong>{{ paymentRate }}%</strong><small>收付款执行率</small></div></div><div class="health-metrics"><div class="health-row"><span><b>已执行金额</b><small>已收 + 已付</small></span><strong>{{ money(overview?.paidTotal) }}</strong></div><div class="health-row"><span><b>计划总额</b><small>收付款计划</small></span><strong>{{ money(overview?.paymentTotal) }}</strong></div><div class="health-row"><span><b>待付款项</b><small>未逾期</small></span><strong>{{ overview?.paymentPending ?? 0 }}</strong></div><div class="health-row"><span><b>待办履行节点</b><small>未逾期</small></span><strong>{{ overview?.milestonePending ?? 0 }}</strong></div></div></div></section><section class="panel ai-panel"><div class="section-heading"><div><h2>AI 审查态势</h2><p class="section-caption">法律审查风险等级分布</p></div><button class="link-button" @click="navigate('ledger')">去审查 →</button></div><div class="ai-body"><div class="risk-bars"><div class="risk-line"><span class="risk-tag risk-high">高</span><div class="risk-track"><b class="risk-fill risk-fill-high" :style="{ width: riskPct('3') + '%' }"></b></div><strong>{{ riskPct('3') }}%</strong></div><div class="risk-line"><span class="risk-tag risk-mid">中</span><div class="risk-track"><b class="risk-fill risk-fill-mid" :style="{ width: riskPct('2') + '%' }"></b></div><strong>{{ riskPct('2') }}%</strong></div><div class="risk-line"><span class="risk-tag risk-low">低</span><div class="risk-track"><b class="risk-fill risk-fill-low" :style="{ width: riskPct('1') + '%' }"></b></div><strong>{{ riskPct('1') }}%</strong></div></div><div class="ai-foot"><span>已审查 {{ aiRiskTotal }} 份 · AI 处理失败 {{ overview?.aiFailed ?? 0 }}</span><button class="secondary-action" @click="navigate('ledger')">发起法律审查</button></div></div></section></div><section class="panel contracts-panel"><div class="section-heading"><div><h2>最近更新合同</h2><p class="section-caption">最近发生操作的合同，点击进入完整详情</p></div><div class="table-tools"><span>{{ contracts.length }} 份合同</span><button class="link-button" @click="navigate('ledger')">查看全部 →</button></div></div><div v-if="contracts.length" class="workspace-table"><div class="workspace-table-head"><span>合同名称</span><span>合同类型</span><span>交易对方</span><span>业务状态</span><span>最近更新</span><span>操作</span></div><button v-for="item in contracts.slice(0,6)" :key="item.id" class="workspace-table-row" @click="openContract(item.id)"><span><b>{{ item.name }}</b><small>{{ item.contractNo }}</small></span><span>{{ item.typeName }}</span><span>{{ item.partyName }}</span><span><i class="status-tag">{{ item.status }}</i></span><span>{{ new Date(item.updatedAt).toLocaleDateString('zh-CN') }}</span><span class="row-action">查看详情 →</span></button></div><div v-else class="empty-state dashboard-empty"><strong>还没有合同数据</strong><span>创建第一份合同后，合同状态和最近更新会显示在这里。</span><button class="primary-action" @click="startCreate">创建第一份合同</button></div></section></section>
      <section v-if="false" class="page-section"><div class="page-header"><div><p class="eyebrow">Configuration</p><h1>合同模板</h1><p class="page-desc">创建和发布模板，已发布模板才能用于新建合同。</p></div></div><div class="content-grid"><section class="panel form-panel"><h2>新增模板</h2><div class="form-grid"><label>模板名称<input v-model="templateForm.name" placeholder="例如：通用服务合同" /></label><label>合同类型<select v-model.number="templateForm.typeId"><option v-for="type in types" :key="type.id" :value="type.id">{{ type.name }} · {{ type.subtype }}</option></select></label><label class="full-width">模板正文<textarea v-model="templateForm.content" rows="11" /></label></div><div class="form-footer"><span class="muted">支持合同名称、合同编号和交易对方变量</span><button class="primary-action" @click="createTemplate">保存模板</button></div></section><section class="panel"><div class="section-heading"><h2>模板列表</h2><span class="muted">{{ templates.length }} 个</span></div><div v-if="templates.length" class="version-list"><div v-for="item in templates" :key="item.id"><span><b>{{ item.name }}</b><small>{{ item.typeName }} · v{{ item.versionNo }}</small></span><span><i class="status-tag">{{ item.status === 'PUBLISHED' ? '已发布' : '草稿' }}</i><button v-if="item.status !== 'PUBLISHED'" class="link-button" @click="action(`/api/templates/${item.id}/publish`)">发布</button></span></div></div><div v-else class="inline-empty">暂无模板</div></section></div></section>
      <section v-else-if="false && view === 'create'" />
      <section v-else-if="view === 'detail' && selected" class="page-section"><div class="page-header"><div><button class="back-button" @click="view='ledger'">← 返回台账</button><p class="eyebrow">Contract detail</p><h1>{{ selected.name }}</h1><p class="page-desc">{{ selected.contractNo }} · {{ selected.typeName }} · {{ selected.partyName }}</p></div><div class="action-group"><span class="status-tag large">{{ selected.status }}</span><button v-if="selected.status === '草稿' && approval?.status !== 'PENDING'" class="primary-action" @click="editSelected">编辑草稿</button><button v-if="selected.status === '履行中'" class="secondary-action" @click="action(`/api/contracts/${selected.id}/status?target=已终止`)">终止合同</button></div></div><div class="detail-grid"><section class="panel"><h2>合同概览</h2><dl class="detail-list"><div><dt>合同类型</dt><dd>{{ selected.typeName }}</dd></div><div><dt>交易对方</dt><dd>{{ selected.partyName }} · {{ selected.relationType }}</dd></div><div><dt>合同编号</dt><dd>{{ selected.contractNo }}</dd></div><div><dt>备注</dt><dd>{{ selected.remark || '暂无' }}</dd></div></dl></section><section class="panel"><h2>操作记录</h2><div class="timeline"><div v-for="entry in selected.auditEntries" :key="entry.operatedAt" class="timeline-row"><span class="timeline-dot"></span><span><b>{{ entry.description }}</b><small>{{ new Date(entry.operatedAt).toLocaleString('zh-CN') }}</small></span></div></div></section></div><div class="detail-grid detail-lower"><section class="panel"><div class="section-heading"><h2>正文版本</h2><span class="muted">{{ selected.contentVersions.length }} 个版本</span></div><textarea v-model="content" class="content-editor" rows="8" :disabled="approval?.status === 'PENDING'" placeholder="输入正文并保存新版本" /><div class="form-footer"><button class="secondary-action" :disabled="approval?.status === 'PENDING'" @click="saveContent">保存新版本</button><label class="secondary-action upload-button">上传附件<input ref="uploadInput" type="file" hidden @change="uploadFile" /></label></div><div class="version-list"><div v-for="item in selected.contentVersions" :key="item.id"><b>v{{ item.versionNo }}</b><span>{{ item.source }} · {{ item.contentHash.slice(0,12) }}</span><i v-if="item.current">当前</i></div><div v-for="file in selected.attachments" :key="file.id"><b>{{ file.fileName }}</b><span>附件 · {{ Math.round(file.fileSize / 1024) }} KB</span></div></div></section><section class="panel"><h2>智能与审批</h2><div class="action-group compact"><button class="secondary-action" :disabled="approval?.status === 'PENDING'" @click="action(`/api/contracts/${selected.id}/ai/extract`)">发起解析</button><button class="secondary-action" :disabled="approval?.status === 'PENDING'" @click="action(`/api/contracts/${selected.id}/ai/review`)">法律审查</button><button v-if="selected.status === '草稿' && approval?.status !== 'PENDING'" class="secondary-action" @click="action(`/api/contracts/${selected.id}/approval`)">提交审批</button><button v-if="approval?.status === 'PENDING'" class="secondary-action" @click="action(`/api/contracts/${selected.id}/approval/approve`)">模拟通过</button><button v-if="approval?.status === 'PENDING'" class="link-button" @click="action(`/api/contracts/${selected.id}/approval/reject`, { opinion: '模拟审批驳回' })">模拟驳回</button><button v-if="approval?.status === 'PENDING'" class="link-button" @click="action(`/api/contracts/${selected.id}/approval/withdraw`, { opinion: '发起人撤回' })">撤回审批</button><button v-if="review && !review.confirmed" class="link-button" @click="confirmReview">确认审查结果</button></div><p v-if="approval" class="section-caption">审批单 {{ approval.approvalNo }} · {{ approval.status === 'PENDING' ? '审批中，正文和关键字段已锁定' : approval.status === 'APPROVED' ? '已通过，等待签署生效' : approval.status === 'REJECTED' ? '已驳回，可修改后重新提交' : '已撤回，可修改后重新提交' }}</p><div v-if="tasks.length" class="task-list"><div v-for="task in tasks" :key="task.id"><b>{{ task.taskType }}</b><small>{{ task.status }} · {{ task.summary }}</small></div></div><div v-if="review" class="review-box"><b>整体风险：{{ review.overallLevel }}</b><p>{{ review.summary }}</p><div v-for="risk in review.risks" :key="risk.riskPoint" class="risk-row"><b>{{ risk.level }} · {{ risk.riskPoint }}</b><span>{{ risk.advice }}</span></div></div></section></div><section v-if="selected.status === '履行中'" class="panel fulfillment-panel"><div class="section-heading"><h2>履行管理</h2><span class="muted">付款与节点</span></div><div class="fulfillment-grid"><div><h3>收付款计划</h3><div class="inline-form"><input v-model="paymentForm.itemName" placeholder="款项名称" /><select v-model="paymentForm.direction"><option value="PAY">我方付款</option><option value="RECEIVE">我方收款</option></select><input v-model.number="paymentForm.amount" type="number" min="0" placeholder="金额" /><input v-model="paymentForm.dueDate" type="date" /><button class="secondary-action" @click="addPayment">新增</button></div><div v-for="item in payments" :key="item.id" class="list-row"><span><b>{{ item.itemName }} · {{ item.amount }}</b><small>{{ item.dueDate }} · {{ item.direction === 'PAY' ? '付款' : '收款' }}</small></span><i class="status-tag">{{ item.status }}</i></div><p v-if="!payments.length" class="inline-empty">暂无计划</p></div><div><h3>履行节点</h3><div class="inline-form"><input v-model="milestoneForm.name" placeholder="节点名称" /><input v-model="milestoneForm.dueDate" type="date" /><button class="secondary-action" @click="addMilestone">新增</button></div><div v-for="item in milestones" :key="item.id" class="list-row"><span><b>{{ item.name }}</b><small>{{ item.dueDate }}</small></span><i class="status-tag">{{ item.status }}</i></div><p v-if="!milestones.length" class="inline-empty">暂无节点</p></div></div></section></section>
      <section v-else-if="false" class="page-section"><div class="page-header"><div><p class="eyebrow">合同中心</p><h1>履行与收付款</h1><p class="page-desc">查看履行中的合同、收付款计划和履行节点。</p></div></div><section class="panel"><div class="section-heading"><h2>履行中的合同</h2><span class="muted">{{ contracts.filter(item => item.status === '履行中').length }} 份</span></div><div v-if="contracts.filter(item => item.status === '履行中').length" class="recent-list"><button v-for="item in contracts.filter(item => item.status === '履行中')" :key="item.id" class="recent-row" @click="openContract(item.id)"><span class="doc-icon">DOC</span><span class="row-main"><b>{{ item.name }}</b><small>{{ item.contractNo }} · {{ item.partyName }}</small></span><span class="tag">进入详情</span></button></div><div v-else class="empty-state"><strong>暂无履行中的合同</strong><span>合同进入履行中后会显示在这里。</span></div></section></section>
      <ContractLedgerWorkspace v-if="view === 'ledger'" :contracts="contracts" :types="types" :can-create="currentUser.permissions.includes('EDIT')" :initial-status="ledgerStatus" @open="openContract" @create="startCreate" />
      <FulfillmentWorkspace v-if="view === 'fulfillment'" :api="api" :role="mockIdentity.role" :user-id="mockIdentity.id" :org-id="mockIdentity.orgId" :department-id="mockIdentity.departmentId" />
      <ChangeWorkspace v-if="view === 'changes' && selected" :api="api" :role="currentUser.role" :contract-id="selected.id" @back="view='detail'" />
      <ContractAuthorizationWorkspace v-if="view === 'authorization' && selected" :api="api" :role="currentUser.role" :user-id="mockIdentity.id" :org-id="mockIdentity.orgId" :department-id="mockIdentity.departmentId" :contract-id="selected.id" :contract-name="selected.name" @back="view='detail'" />
      <BaseConfigWorkspace v-if="view === 'base-config'" :api="api" :role="currentUser.role" :types="types" />
      <AdminUserWorkspace v-if="view === 'accounts'" :api="api" :role="currentUser.role" />
      <FormalContractPanel v-if="view === 'detail' && selected" :detail="selected" />
      <AiExtractionReview v-if="view === 'detail' && selected" :api="api" :detail="selected" :role="mockIdentity.role" :user-id="mockIdentity.id" :org-id="mockIdentity.orgId" :department-id="mockIdentity.departmentId" @updated="openContract(selected.id)" />
      <section v-if="view === 'detail' && selected && detailTab === 'archive'" class="page-section detail-archive-page">
        <section class="panel detail-archive-card">
          <div class="section-heading"><div><p class="eyebrow">CHANGE &amp; ARCHIVE</p><h2>变更与归档</h2><p class="section-caption">补充协议、内容变更与归档均保留独立审批和可追溯记录。</p></div><span class="status-tag">{{ selected.archived ? '已归档' : '可继续管理' }}</span></div>
          <div class="detail-archive-actions"><div><b>发起变更或补充协议</b><span>变更在审批生效前不会覆盖当前合同正文。</span></div><button v-if="!selected.archived" class="primary-action" @click="view='changes'">进入变更管理</button><span v-else class="muted">该合同已归档，历史变更仅供查阅。</span></div>
          <div class="detail-archive-actions"><div><b>合同归档</b><span>{{ selected.archived ? '归档后的正文、文件、履约和收付款均为只读。' : '仅已完成或已终止的合同可归档。' }}</span></div><button v-if="!selected.archived && (selected.status === '已完成' || selected.status === '已终止')" class="secondary-action" @click="action(`/api/contracts/${selected.id}/archive`)">归档合同</button></div>
        </section>
      </section>
      <CreateContractWorkspace v-if="view === 'create'" :api="api" :role="currentUser.role" :form="form" :types="types" :parties="parties" :templates="templates" :editing="Boolean(selected)" :loading="loading" @back="selected ? openContract(selected.id) : view='workspace'" @save="saveDraft" />
      <SignedContractRegistration v-if="view === 'register'" :path="registrationPath" :api="api" :role="mockIdentity.role" :user-id="mockIdentity.id" :org-id="mockIdentity.orgId" :department-id="mockIdentity.departmentId" :types="types" :parties="parties" @back="navigate('ledger')" @draft="navigate('create')" @saved="openRegisteredContract" />
    </main>
  </div>
  <section v-if="view === 'detail' && selected && !selected.archived && (selected.status === '已完成' || selected.status === '已终止')" class="signing-dock"><div><strong>合同归档</strong><small>归档后正文、附件、履约、收付款和变更均只读，历史数据仍可查询。</small></div><button class="secondary-action" @click="action(`/api/contracts/${selected.id}/archive`)">归档合同</button></section>
  <section v-if="view === 'workspace'" class="page-section"><section class="panel contracts-panel"><div class="section-heading"><div><h2>风险与到期待办</h2><p class="section-caption">仅显示当前权限范围内需要处理的合同事项</p></div><span class="attention-actions"><span class="muted">{{ notificationCount }} 项待处理</span><button v-if="currentUser.permissions.includes('EXPORT')" class="secondary-action" @click="exportAnalysis">导出分析</button></span></div><div v-if="attentionItems.length" class="recent-list"><div v-for="item in attentionItems.slice(0, 8)" :key="item.key" class="recent-row attention-row" role="button" tabindex="0" @click="openAttention(item)" @keydown.enter="openAttention(item)"><span class="doc-icon">!</span><span class="row-main"><b>{{ item.title }} · {{ item.contractName }}</b><small>{{ item.contractNo }} · {{ item.detail }}{{ item.dueDate ? ` · ${item.dueDate}` : '' }}</small><small v-if="item.handlingStatus !== 'OPEN'">{{ item.handlingStatus === 'PROCESSED' ? '已处理' : '已忽略' }} · {{ item.handledBy }} · {{ item.handledAt ? new Date(item.handledAt).toLocaleString('zh-CN') : '' }}{{ item.handlingOpinion ? ` · ${item.handlingOpinion}` : '' }}</small></span><span class="attention-actions" @click.stop><span v-if="item.escalated" class="tag danger">已升级</span><span class="tag">{{ item.handlingStatus === 'OPEN' ? (item.severity === 'HIGH' ? '高优先级' : '待处理') : (item.handlingStatus === 'PROCESSED' ? '已处理' : '已忽略') }}</span><button v-if="item.handlingStatus === 'OPEN' && currentUser.permissions.includes('EDIT')" class="link-button" @click="updateAttention(item, 'PROCESSED')">处理</button><button v-if="item.handlingStatus === 'OPEN' && currentUser.permissions.includes('EDIT')" class="link-button" @click="updateAttention(item, 'IGNORED')">忽略</button><button v-if="item.handlingStatus !== 'OPEN' && currentUser.permissions.includes('EDIT')" class="link-button" @click="updateAttention(item, 'OPEN')">重新打开</button></span></div></div><div v-else class="inline-empty">当前没有需要处理的风险或到期事项</div></section></section>
</template>
